VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: begins with a vowel, or starts with "xr" or "yt".
    if word[0] in VOWELS or word[:2] in ("xr", "yt"):
        return word + "ay"

    # Find where the leading consonant cluster ends.
    for i, c in enumerate(word):
        # Rule 3: consonants followed by "qu" -> move the "qu" along with them.
        if c == "q" and i + 1 < len(word) and word[i + 1] == "u":
            split = i + 2
            break
        # Rule 4: "y" counts as a vowel once it is no longer the first letter.
        if c == "y" and i > 0:
            split = i
            break
        # Rule 2: the first true vowel ends the consonant cluster.
        if c in VOWELS:
            split = i
            break
    else:
        split = len(word)

    return word[split:] + word[:split] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split(" "))
